boss_predict.rs.src:
fn main() {
    let mut steps = 0;
    let mut n = 6;
    let total = loop {
        if n == 1 {
            break steps;
        }
        if n % 2 == 0 {
            n /= 2;
        } else {
            n = 3 * n + 1;
        }
        steps += 1;
        print!("{n} ");
    };
    println!();
    println!("{total} steps");
}

